const history={t:[],cpu:[],ram:[],tok:[]};
const sysCtx=document.getElementById('sysChart');
const ownerCtx=document.getElementById('ownerChart');
const sysChart=new Chart(sysCtx,{type:'line',data:{labels:[],datasets:[
  {label:'CPU %',data:[],borderColor:'#60a5fa'},
  {label:'RAM %',data:[],borderColor:'#34d399'},
  {label:'Disk %',data:[],borderColor:'#f59e0b'}
]},options:{animation:false,responsive:true,scales:{y:{min:0,max:100}}}});
let ownerChart=null;

function fmtBytes(n){const u=['B','KB','MB','GB','TB'];let i=0;while(n>1024&&i<u.length-1){n/=1024;i++;}return n.toFixed(1)+u[i]}
function ragClass(r){return r==='RED'?'rag-red':(r==='AMBER'?'rag-amber':'rag-green')}

async function tick(){
  const r=await fetch('/api/metrics');
  const d=await r.json();
  document.getElementById('ts').textContent='Updated: '+new Date(d.timestamp).toLocaleString();
  document.getElementById('cpu').textContent=d.system.cpuPercent+'%';
  document.getElementById('ram').textContent=d.system.memory.usedPct+'%';
  document.getElementById('tok').textContent=d.projects.tokenToday.total;
  document.getElementById('blk').textContent=d.projects.blockerCount;

  const label=new Date().toLocaleTimeString();
  sysChart.data.labels.push(label);
  sysChart.data.datasets[0].data.push(d.system.cpuPercent);
  sysChart.data.datasets[1].data.push(d.system.memory.usedPct);
  sysChart.data.datasets[2].data.push(d.system.disk.usedPct);
  if(sysChart.data.labels.length>30){
    sysChart.data.labels.shift();
    sysChart.data.datasets.forEach(x=>x.data.shift());
  }
  sysChart.update();

  document.getElementById('rag').innerHTML=`
    <div><span class="pill p-green">GREEN ${d.projects.ragCounts.GREEN||0}</span>
    <span class="pill p-amber">AMBER ${d.projects.ragCounts.AMBER||0}</span>
    <span class="pill p-red">RED ${d.projects.ragCounts.RED||0}</span></div>`;

  const owners=d.projects.ownerActivity;
  const labels=Object.keys(owners), values=Object.values(owners);
  if(!ownerChart){
    ownerChart=new Chart(ownerCtx,{type:'bar',data:{labels,datasets:[{label:'Owner activity',data:values,backgroundColor:'#8b5cf6'}]},options:{animation:false}})
  }else{
    ownerChart.data.labels=labels; ownerChart.data.datasets[0].data=values; ownerChart.update();
  }

  document.getElementById('proc').innerHTML=d.system.topProcesses.map(p=>`<tr><td>${p.name}</td><td>${p.cpu}</td><td>${p.mem}</td></tr>`).join('');
  document.getElementById('recs').innerHTML=d.recommendations.map(x=>`<li>${x}</li>`).join('');
  document.getElementById('updates').innerHTML=d.projects.updates.slice(-12).reverse().map(u=>`<li class="${ragClass(u.rag)}">[${u.rag}] ${u.text}</li>`).join('');
}

tick();
setInterval(tick,5000);
</script>
