#!/usr/bin/env python3
import json
import os
import re
import shutil
import subprocess
import time
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

WORKSPACE = Path('/home/openclaw_user/.openclaw/workspace')
TEAM_LOGS = WORKSPACE / 'team_logs'
SESSIONS_META = Path('/home/openclaw_user/.openclaw/agents/main/sessions/sessions.json')
PUBLIC_DIR = Path(__file__).parent / 'public'

CPU_LAST = None
CPU_LAST_TS = None


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        return ''


def cpu_usage_percent():
    global CPU_LAST, CPU_LAST_TS
    try:
        with open('/proc/stat', 'r', encoding='utf-8') as f:
            line = f.readline()
        parts = [float(x) for x in line.strip().split()[1:]]
        idle = parts[3] + parts[4]
        total = sum(parts)
        now = time.time()
        if CPU_LAST is None:
            CPU_LAST = (idle, total)
            CPU_LAST_TS = now
            return 0.0
        prev_idle, prev_total = CPU_LAST
        delta_idle = idle - prev_idle
        delta_total = total - prev_total
        CPU_LAST = (idle, total)
        CPU_LAST_TS = now
        if delta_total <= 0:
            return 0.0
        return round(100.0 * (1.0 - delta_idle / delta_total), 1)
    except Exception:
        return 0.0


def mem_info():
    out = {}
    try:
        with open('/proc/meminfo', 'r', encoding='utf-8') as f:
            for line in f:
                k, v = line.split(':', 1)
                out[k.strip()] = int(v.strip().split()[0]) * 1024
    except Exception:
        pass
    return out


def get_session_file():
    try:
        data = json.loads(read_text(SESSIONS_META) or '{}')
        if not data:
            return None
        # ưu tiên session telegram direct của anh Minh
        key = None
        for k in data.keys():
            if 'telegram:direct:1079299777' in k:
                key = k
                break
        if key is None:
            key = next(iter(data.keys()))
        sf = data[key].get('sessionFile')
        return Path(sf) if sf else None
    except Exception:
        return None


def token_stats_today():
    session_file = get_session_file()
    if not session_file or not session_file.exists():
        return {'in': 0, 'out': 0, 'total': 0, 'messages': 0}

    today = datetime.now(timezone.utc).date().isoformat()
    token_in = 0
    token_out = 0
    count = 0
    try:
        with session_file.open('r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                ts = obj.get('timestamp', '')
                if not ts.startswith(today):
                    continue
                msg = obj.get('message', {})
                usage = msg.get('usage', {})
                i = usage.get('input', 0) or 0
                o = usage.get('output', 0) or 0
                if i or o:
                    token_in += int(i)
                    token_out += int(o)
                    count += 1
    except Exception:
        pass
    return {'in': token_in, 'out': token_out, 'total': token_in + token_out, 'messages': count}


def parse_team_updates(limit=25):
    files = sorted(TEAM_LOGS.glob('*.md'))
    if not files:
        return []
    latest = files[-1]
    lines = read_text(latest).splitlines()
    updates = []
    for ln in lines:
        if ln.startswith('- '):
            text = ln[2:].strip()
            rag = 'GREEN'
            up = text.upper()
            if 'RAG: RED' in up or ' RED ' in up:
                rag = 'RED'
            elif 'RAG: AMBER' in up or ' AMBER' in up:
                rag = 'AMBER'
            updates.append({'text': text, 'rag': rag})
    return updates[-limit:]


def owner_activity(updates):
    owners = {'Mạnh AI': 0, 'Huy AI': 0, 'Hà AI': 0, 'Huyền AI': 0, 'MINH AI': 0}
    for u in updates:
        t = u['text']
        for name in list(owners.keys()):
            if name in t:
                owners[name] += 1
    return owners


def top_processes():
    try:
        out = subprocess.check_output(
            "ps -eo comm,%cpu,%mem --sort=-%cpu | head -n 8",
            shell=True,
            text=True,
            stderr=subprocess.DEVNULL,
        )
        rows = []
        for ln in out.splitlines()[1:]:
            parts = ln.split()
            if len(parts) >= 3:
                rows.append({'name': parts[0], 'cpu': float(parts[1]), 'mem': float(parts[2])})
        return rows
    except Exception:
        return []


def build_payload():
    now = datetime.now(timezone.utc).isoformat()
    cpu = cpu_usage_percent()
    load1, load5, load15 = os.getloadavg()
    mem = mem_info()

    mem_total = mem.get('MemTotal', 0)
    mem_avail = mem.get('MemAvailable', 0)
    mem_used = max(mem_total - mem_avail, 0)
    mem_pct = round((mem_used / mem_total * 100), 1) if mem_total else 0

    swap_total = mem.get('SwapTotal', 0)
    swap_free = mem.get('SwapFree', 0)
    swap_used = max(swap_total - swap_free, 0)
    swap_pct = round((swap_used / swap_total * 100), 1) if swap_total else 0

    disk = shutil.disk_usage('/')
    disk_pct = round((disk.used / disk.total * 100), 1)

    tokens = token_stats_today()
    updates = parse_team_updates()
    owners = owner_activity(updates)

    rag_counts = {'GREEN': 0, 'AMBER': 0, 'RED': 0}
    blocker_count = 0
    for u in updates:
        rag_counts[u['rag']] = rag_counts.get(u['rag'], 0) + 1
        if 'blocker' in u['text'].lower() or 'blocked' in u['text'].lower():
            blocker_count += 1

    recs = []
    if cpu > 80:
        recs.append('CPU cao >80%: kiểm tra tiến trình tiêu tốn CPU và cân nhắc scale.')
    if mem_pct > 85:
        recs.append('RAM >85%: theo dõi memory leak, tăng swap hoặc nâng RAM.')
    if disk_pct > 80:
        recs.append('Disk >80%: cần dọn log/artifact hoặc mở rộng volume.')
    if load1 > os.cpu_count():
        recs.append('Load 1m vượt số core: có nguy cơ nghẽn xử lý.')
    if blocker_count > 0:
        recs.append(f'Có {blocker_count} mục blocker trong log gần nhất: ưu tiên xử lý ngay.')
    if not recs:
        recs.append('Hệ thống ổn định. Duy trì theo dõi realtime mỗi 5 giây.')

    return {
        'timestamp': now,
        'system': {
            'cpuPercent': cpu,
            'load': {'l1': round(load1, 2), 'l5': round(load5, 2), 'l15': round(load15, 2)},
            'memory': {'total': mem_total, 'used': mem_used, 'available': mem_avail, 'usedPct': mem_pct},
            'swap': {'total': swap_total, 'used': swap_used, 'free': swap_free, 'usedPct': swap_pct},
            'disk': {'total': disk.total, 'used': disk.used, 'free': disk.free, 'usedPct': disk_pct},
            'topProcesses': top_processes(),
        },
        'projects': {
            'tokenToday': tokens,
            'ragCounts': rag_counts,
            'blockerCount': blocker_count,
            'updates': updates,
            'ownerActivity': owners,
        },
        'recommendations': recs,
    }


class Handler(BaseHTTPRequestHandler):
    def _json(self, data, code=200):
        b = json.dumps(data, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == '/api/metrics':
            return self._json(build_payload())

        if path == '/health':
            return self._json({'ok': True, 'time': datetime.now(timezone.utc).isoformat()})

        # static files
        file_path = PUBLIC_DIR / ('index.html' if path == '/' else path.lstrip('/'))
        if file_path.exists() and file_path.is_file() and str(file_path.resolve()).startswith(str(PUBLIC_DIR.resolve())):
            ctype = 'text/html; charset=utf-8'
            if file_path.suffix == '.js':
                ctype = 'application/javascript; charset=utf-8'
            elif file_path.suffix == '.css':
                ctype = 'text/css; charset=utf-8'
            content = file_path.read_bytes()

