    if not detail:
        detail = 'Không có chi tiết kỹ thuật bổ sung.'
    return detail


def detect_speaker(text: str) -> str:
    order = ['Mạnh AI', 'Huy AI', 'Hà AI', 'Huyền AI', 'MINH AI']
