class Handler(BaseHTTPRequestHandler):
    def _is_authorized(self):
        # Nếu không set password thì tạm thời mở (phục vụ local dev)
        if not AUTH_PASS:
            return True
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Basic '):
            return False
        try:
            raw = base64.b64decode(auth.split(' ', 1)[1]).decode('utf-8', errors='ignore')
            user, pw = raw.split(':', 1)
            return user == AUTH_USER and pw == AUTH_PASS
        except Exception:
            return False

    def _deny(self):
        self.send_response(401)
        self.send_header('WWW-Authenticate', 'Basic realm="Ops Cockpit"')
        self.end_headers()

    def _json(self, data, code=200):
        b = json.dumps(data, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if path == '/health':
            return self._json({'ok': True, 'time': datetime.now(timezone.utc).isoformat()})

        if not self._is_authorized():
            return self._deny()

        if path == '/api/metrics':
            return self._json(build_payload())

        # static files
        file_path = PUBLIC_DIR / ('index.html' if path == '/' else path.lstrip('/'))
        if file_path.exists() and file_path.is_file() and str(file_path.resolve()).startswith(str(PUBLIC_DIR.resolve())):
            ctype = 'text/html; charset=utf-8'
            if file_path.suffix == '.js':
                ctype = 'application/javascript; charset=utf-8'
            elif file_path.suffix == '.css':
                ctype = 'text/css; charset=utf-8'
            content = file_path.read_bytes()
            self.send_response(200)
            self.send_header('Content-Type', ctype)
            self.send_header('Content-Length', str(len(content)))
            self.end_headers()
            self.wfile.write(content)
            return

        self.send_response(404)
        self.end_headers()


