def extract_technical_details_vi(text: str) -> str:
    details = []
    markers = ['Bằng chứng:', 'Vướng mắc:', 'Hạn dự kiến:', 'Bước tiếp theo:', 'RAG:', 'Quyết định:', 'Phụ trách:']
    for mk in markers:
        idx = text.find(mk)
        if idx != -1:
            details.append(text[idx:])
            break

    if not details:
        details.append(text)

    detail = details[0].strip()
    if not detail:
        detail = 'Không có chi tiết kỹ thuật bổ sung.'
    return detail

edits.newText:
def _extract_field(text: str, labels: list[str]) -> str:
    points = []
    all_labels = [
        'Quyết định:', 'Phụ trách:', 'Vướng mắc:', 'Hạn dự kiến:', 'Bước tiếp theo:', 'Bằng chứng:',
        'Decision:', 'Owners:', 'Owner:', 'Blockers:', 'ETA:', 'Next:', 'Evidence:'
    ]
    for lb in labels:
        idx = text.find(lb)
        if idx != -1:
            start = idx + len(lb)
            end = len(text)
            for x in all_labels:
                j = text.find(x, start)
                if j != -1:
                    end = min(end, j)
            points.append(text[start:end].strip(' .;'))
    return points[0] if points else ''


def _normalize_vi_phrase(text: str) -> str:
    repl = {
        'pending': 'đang chờ',
        'none': 'không có',
        'service': 'dịch vụ',
        'running': 'đang chạy',
        'feature': 'tính năng',
        'dashboard': 'bảng điều hành',
        'hardening': 'gia cố bảo mật',
        'restart': 'khởi động lại',
        'scope': 'phạm vi',
        'requirement': 'yêu cầu',
        'contract': 'hợp đồng giao tiếp',
        'evidence': 'bằng chứng',
        'blocker': 'điểm nghẽn',
        'sync': 'đồng bộ',
    }
    out = text
    for k, v in repl.items():
        out = re.sub(rf'\b{k}\b', v, out, flags=re.IGNORECASE)
    return out


def extract_technical_details_vi(text: str) -> str:
    t = to_vietnamese_text(text)

    decision = _extract_field(t, ['Quyết định:', 'Decision:'])
    owners = _extract_field(t, ['Phụ trách:', 'Owners:', 'Owner:'])
    blockers = _extract_field(t, ['Vướng mắc:', 'Blockers:'])
    eta = _extract_field(t, ['Hạn dự kiến:', 'ETA:'])
    next_step = _extract_field(t, ['Bước tiếp theo:', 'Next:'])
    evidence = _extract_field(t, ['Bằng chứng:', 'Evidence:'])

    lines = []
    if decision:
        lines.append('• Quyết định: ' + _normalize_vi_phrase(decision))
    if owners:
        lines.append('• Phụ trách: ' + _normalize_vi_phrase(owners))
    if eta:
        lines.append('• Hạn dự kiến: ' + _normalize_vi_phrase(eta))
    if blockers:
        lines.append('• Vướng mắc: ' + _normalize_vi_phrase(blockers))
    if next_step:
        lines.append('• Bước tiếp theo: ' + _normalize_vi_phrase(next_step))
    if evidence:
        lines.append('• Bằng chứng: ' + _normalize_vi_phrase(evidence))

    if not lines:
        fallback = summarize_non_technical_vi(t)
        lines.append('• Tóm tắt kỹ thuật: ' + fallback)

    detail = '\n'.join(lines).strip()
    return detail if detail else 'Không có chi tiết kỹ thuật bổ sung.'

