def detect_speaker(text: str) -> str:
    names = ['MINH AI', 'Mạnh AI', 'Huy AI', 'Hà AI', 'Huyền AI']
    pos = []
    for n in names:
        i = text.find(n)
        if i != -1:
            pos.append((i, n))
    if pos:
        pos.sort(key=lambda x: x[0])
        return pos[0][1]
    if 'User' in text or 'Anh Minh' in text:
        return 'Anh Minh'
    return 'MINH AI'


def extract_owner_messages(text: str):
    out = []
    m = re.search(r'(Owners\s*&\s*ETA:|Phụ trách\s*&\s*Hạn dự kiến:)(.*?)(Blockers:|Vướng mắc:|$)', text, re.IGNORECASE)
    if not m:
        return out
    body = m.group(2).strip()
    parts = [p.strip(' .') for p in body.split(';') if p.strip()]
    for p in parts:
        m2 = re.match(r'^(Mạnh AI|Huy AI|Hà AI|Huyền AI|MINH AI)\s*(.*)$', p)
        if not m2:
            continue
        speaker = m2.group(1)
        content = m2.group(2).strip(' .,:')
        if content:
            out.append({'speaker': speaker, 'text': f'Em cập nhật: {content}.'})
    return out


