def summarize_non_technical_vi(text: str) -> str:
    cleaned = text
    for mk in [' Bằng chứng:', ' Vướng mắc:', ' Hạn dự kiến:', ' Bước tiếp theo:', ' RAG:', ' Quyết định:', ' Phụ trách:']:
        idx = cleaned.find(mk)
        if idx != -1:
            cleaned = cleaned[:idx]
    cleaned = cleaned.strip(' .;')

    low = cleaned.lower()

    # Mẫu tóm tắt ưu tiên tiếng Việt, dễ đọc trên mobile
    if 'hiding technical content' in low or 'ẩn nội dung kỹ thuật' in low:
        return 'Anh Minh yêu cầu ẩn nội dung kỹ thuật mặc định và cho phép bấm xem thêm theo từng tin nhắn.'
    if 'chat conversation in vietnamese' in low or 'hội thoại' in low:
        return 'Đội bot cập nhật: phần trao đổi nội bộ đã chuyển sang dạng hội thoại tiếng Việt.'
    if 'production hardening' in low or 'hardening' in low:
        return 'Đội bot báo đã hoàn tất hardening bản dashboard và xác thực truy cập.'
    if 'visual monitoring ui' in low or 'monitoring' in low:
        return 'Anh Minh yêu cầu dashboard trực quan realtime để theo dõi tiến độ, lỗi và hiệu suất VPS.'
    if 'hourly pm report' in low or 'báo cáo giờ' in low:
        return 'MINH AI đã phát hành báo cáo giờ với trạng thái RAG và các rủi ro cần xử lý.'
    if 'internal scrum sync' in low or 'scrum sync' in low:
        return 'Các bot đã đồng bộ nhanh, chốt đầu việc và mốc giờ thực thi trong phiên hiện tại.'

    # Chuẩn hoá một số câu hội thoại tự nhiên
    cleaned = cleaned.replace('Anh Minh hỏi', 'Anh Minh hỏi:')
    cleaned = cleaned.replace('Anh Minh yêu cầu', 'Anh Minh yêu cầu:')
    cleaned = cleaned.replace('Anh Minh đã phê duyệt', 'Anh Minh đã phê duyệt:')

    # Nếu còn nhiều tiếng Anh thì thay bằng bản tóm tắt trung tính tiếng Việt
    ascii_words = re.findall(r'[A-Za-z]{3,}', cleaned)
    if len(ascii_words) >= 8:
        return 'Cập nhật nội bộ: đội bot đang triển khai theo yêu cầu mới của anh Minh.'

    if len(cleaned) < 12:
        cleaned = 'Cập nhật công việc mới từ bot.'
    return cleaned


def _extract_field(text: str, labels: list[str]) -> str:
    points = []
    all_labels = [
        'Quyết định:', 'Phụ trách:', 'Vướng mắc:', 'Hạn dự kiến:', 'Bước tiếp theo:', 'Bằng chứng:',
        'Decision:', 'Owners:', 'Owner:', 'Blockers:', 'ETA:', 'Next:', 'Evidence:'
    ]
    for lb in labels:
        idx = text.find(lb)
        if idx != -1:
            start = idx + len(lb)
            end = len(text)
            for x in all_labels:
                j = text.find(x, start)
                if j != -1:
                    end = min(end, j)
            points.append(text[start:end].strip(' .;'))
    return points[0] if points else ''


def _normalize_vi_phrase(text: str) -> str:
    repl = {
        'pending': 'đang chờ',
        'none': 'không có',
        'service': 'dịch vụ',
        'running': 'đang chạy',
        'feature': 'tính năng',
        'dashboard': 'bảng điều hành',
        'hardening': 'gia cố bảo mật',
        'restart': 'khởi động lại',
        'scope': 'phạm vi',
        'requirement': 'yêu cầu',
        'contract': 'hợp đồng giao tiếp',
        'evidence': 'bằng chứng',
        'blocker': 'điểm nghẽn',
        'sync': 'đồng bộ',
    }
    out = text
    for k, v in repl.items():
        out = re.sub(rf'\b{k}\b', v, out, flags=re.IGNORECASE)
    return out


def _simplify_tech_phrase_vi(text: str) -> str:
    t = _normalize_vi_phrase(text)
    low = t.lower()

    if 'toggle' in low or 'nút' in low or 'ẩn' in low or 'hiện' in low:
        return 'Đã bổ sung cơ chế ẩn/hiện nội dung kỹ thuật theo từng mục và theo từng tin nhắn.'
    if 'api/metrics' in low or ('api' in low and 'metrics' in low):
        return 'API số liệu hoạt động ổn định và trả dữ liệu đầy đủ cho giao diện.'
    if 'systemctl' in low or 'khởi động lại' in low or 'dịch vụ' in low:
        return 'Dịch vụ đã được khởi động lại và đang vận hành ổn định.'
    if 'swap' in low:
        return 'Đã cấu hình bộ nhớ hoán đổi (swap) và tối ưu tham số vận hành.'
    if 'https' in low or 'tls' in low:
        return 'Hạng mục bảo mật đường truyền (HTTPS/TLS) đang được theo dõi theo kế hoạch.'

    ascii_words = re.findall(r'[A-Za-z]{3,}', t)
    if len(ascii_words) >= 6:
        return 'Nội dung kỹ thuật đã được chuẩn hóa và ghi nhận trong hệ thống theo dõi.'

    return t


def extract_technical_details_vi(text: str) -> str:
    t = to_vietnamese_text(text)

    decision = _extract_field(t, ['Quyết định:', 'Decision:'])
    owners = _extract_field(t, ['Phụ trách:', 'Owners:', 'Owner:'])
    blockers = _extract_field(t, ['Vướng mắc:', 'Blockers:'])
    eta = _extract_field(t, ['Hạn dự kiến:', 'ETA:'])
    next_step = _extract_field(t, ['Bước tiếp theo:', 'Next:'])
    evidence = _extract_field(t, ['Bằng chứng:', 'Evidence:'])

    lines = []
    if decision:
        lines.append('• Quyết định: ' + _simplify_tech_phrase_vi(decision))
    if owners:
        lines.append('• Phụ trách: ' + _normalize_vi_phrase(owners))
    if eta:
        lines.append('• Hạn dự kiến: ' + _simplify_tech_phrase_vi(eta))
    if blockers:
        lines.append('• Vướng mắc: ' + _simplify_tech_phrase_vi(blockers))
    if next_step:
        lines.append('• Bước tiếp theo: ' + _simplify_tech_phrase_vi(next_step))
    if evidence:
        lines.append('• Bằng chứng: ' + _simplify_tech_phrase_vi(evidence))

    if not lines:
        fallback = summarize_non_technical_vi(t)
        lines.append('• Tóm tắt kỹ thuật: ' + fallback)

    detail = '\n'.join(lines).strip()
    return detail if detail else 'Không có chi tiết kỹ thuật bổ sung.'


def detect_speaker(text: str) -> str:
    names = ['MINH AI', 'Mạnh AI', 'Huy AI', 'Hà AI', 'Huyền AI']
    pos = []
    for n in names:
        i = text.find(n)
        if i != -1:
            pos.append((i, n))
    if pos:
        pos.sort(key=lambda x: x[0])
        return pos[0][1]
    if 'User' in text or 'Anh Minh' in text:
        return 'Anh Minh'
    return 'MINH AI'


