def top_processes():
    try:
        out = subprocess.check_output(
            "ps -eo comm,%cpu,%mem --sort=-%cpu | head -n 8",
            shell=True,
            text=True,
            stderr=subprocess.DEVNULL,
        )
        rows = []
        for ln in out.splitlines()[1:]:
            parts = ln.split()
            if len(parts) >= 3:
                rows.append({'name': parts[0], 'cpu': float(parts[1]), 'mem': float(parts[2])})
        return rows
    except Exception:
        return []


def build_payload():
    now = datetime.now(timezone.utc).isoformat()
    cpu = cpu_usage_percent()
    load1, load5, load15 = os.getloadavg()
    mem = mem_info()

    mem_total = mem.get('MemTotal', 0)
    mem_avail = mem.get('MemAvailable', 0)
    mem_used = max(mem_total - mem_avail, 0)
    mem_pct = round((mem_used / mem_total * 100), 1) if mem_total else 0

    swap_total = mem.get('SwapTotal', 0)
    swap_free = mem.get('SwapFree', 0)
    swap_used = max(swap_total - swap_free, 0)
    swap_pct = round((swap_used / swap_total * 100), 1) if swap_total else 0

    disk = shutil.disk_usage('/')
    disk_pct = round((disk.used / disk.total * 100), 1)

    tokens = token_stats_today()
    updates = parse_team_updates()
    owners = owner_activity(updates)

    rag_counts = {'GREEN': 0, 'AMBER': 0, 'RED': 0}
    blocker_count = 0
    for u in updates:
        rag_counts[u['rag']] = rag_counts.get(u['rag'], 0) + 1
        if 'blocker' in u['text'].lower() or 'blocked' in u['text'].lower():
            blocker_count += 1

    est_usd = (tokens['in'] / 1_000_000.0) * IN_USD_PER_1M + (tokens['out'] / 1_000_000.0) * OUT_USD_PER_1M
    est_vnd = int(round(est_usd * USD_TO_VND))
    budget_remaining = max(TOKEN_BUDGET_DAILY - tokens['total'], 0)
    budget_remaining_pct = round((budget_remaining / TOKEN_BUDGET_DAILY) * 100, 1) if TOKEN_BUDGET_DAILY > 0 else 0.0

    recs = []
    if cpu > 80:
        recs.append('CPU cao >80%: kiểm tra tiến trình tiêu tốn CPU và cân nhắc scale.')
    if mem_pct > 85:
        recs.append('RAM >85%: theo dõi memory leak, tăng swap hoặc nâng RAM.')
    if disk_pct > 80:
        recs.append('Disk >80%: cần dọn log/artifact hoặc mở rộng volume.')
    if load1 > os.cpu_count():
        recs.append('Load 1m vượt số core: có nguy cơ nghẽn xử lý.')
    if blocker_count > 0:
        recs.append(f'Có {blocker_count} mục blocker trong log gần nhất: ưu tiên xử lý ngay.')
    if budget_remaining_pct < 20:
        recs.append(f'Hạn mức token còn {budget_remaining_pct}%: cần theo dõi để tránh vượt ngân sách trong ngày.')
