    m = re.search(r'(Owners\s*&\s*ETA:|Phụ trách\s*&\s*Hạn dự kiến:)(.*?)(Blockers:|Vướng mắc:|$)', text, re.IGNORECASE)
    if not m:
        return out
    body = m.group(2).strip()
    parts = [p.strip(' .') for p in body.split(';') if p.strip()]
    for p in parts:
        m2 = re.match(r'^(Mạnh AI|Huy AI|Hà AI|Huyền AI|MINH AI)\s*(.*)$', p)
        if not m2:
            continue
        speaker = m2.group(1)
        content = m2.group(2).strip(' .,:')
        if content:
            out.append({'speaker': speaker, 'text': content})
    return out


def humanize_owner_update(speaker: str, content: str) -> str:
    c = _normalize_vi_phrase(content)
    c = c.replace('OpenAPI', 'đặc tả API').replace('SLO', 'mục tiêu mức dịch vụ').replace('UAT', 'kiểm thử nghiệm thu')
    c = c.replace('SIT', 'kiểm thử tích hợp hệ thống').replace('contract-test', 'kiểm thử hợp đồng giao tiếp')
    if speaker == 'Mạnh AI':
        return f'Em cập nhật nhanh: {c}.'
    if speaker == 'Huy AI':
        return f'Phần giao diện em đang xử lý: {c}.'
    if speaker == 'Hà AI':
        return f'Phần máy chủ em đang triển khai: {c}.'
    if speaker == 'Huyền AI':
        return f'Phần phân tích nghiệp vụ em đang theo dõi: {c}.'
    return f'Em cập nhật: {c}.'


def humanize_preview(speaker: str, preview: str) -> str:
    if 'Cập nhật nội bộ: đội bot đang triển khai theo yêu cầu mới của anh Minh.' in preview:
        mapping = {
            'Mạnh AI': 'Em đang bám sát tiến độ kỹ thuật tổng thể, có thay đổi em báo anh ngay.',
            'Huy AI': 'Em đang rà soát giao diện và trải nghiệm người dùng, có bản mới em cập nhật liền.',
            'Hà AI': 'Em đang theo dõi phần máy chủ và dữ liệu, có rủi ro em cảnh báo sớm cho anh.',
            'Huyền AI': 'Em đang tổng hợp yêu cầu và tiêu chí nghiệm thu, để anh theo dõi dễ hơn.',
            'MINH AI': 'Em đang điều phối tiến độ chung và theo dõi các điểm nghẽn theo thời gian thực.'
        }
        return mapping.get(speaker, preview)
    return preview


