def parse_priority_blockers(updates, limit=8):
    items = []
    for u in updates:
        txt = u.get('text', '')
        ts = ''
        m_time = re.match(r'^(\d{2}:\d{2}(?:–\d{2}:\d{2})?\sUTC)\s*[:\-]\s*(.*)$', txt)
        body = txt
        if m_time:
            ts, body = m_time.group(1), m_time.group(2)

        speaker = detect_speaker(to_vietnamese_text(body))

        m = re.search(r'(Blockers:|Vướng mắc:)(.*?)(Next:|Bước tiếp theo:|$)', body, re.IGNORECASE)
        if not m:
            continue
        raw = m.group(2).strip(' .;')
        raw_vi = _normalize_vi_phrase(to_vietnamese_text(raw))
        low = raw_vi.lower()

        if not raw_vi or low in {'none', 'không có'} or low.startswith('không có'):
            continue

        severity = 'AMBER'
        if any(k in low for k in ['blocked', 'đang chờ', 'không xác nhận', 'chưa xác nhận', 'missing', 'thiếu', 'password', 'không có quyền']):
            severity = 'RED'

        items.append({
            'time': ts,
            'speaker': speaker,
            'text': raw_vi,
            'severity': severity,
            'source': summarize_non_technical_vi(to_vietnamese_text(body)),
        })

    def rank(x):
        sev = 2 if x['severity'] == 'RED' else 1
        return (sev, x.get('time', ''))

    items.sort(key=rank, reverse=True)
    return items[:limit]


