function fmtBytes(n){const u=['B','KB','MB','GB','TB'];let i=0;while(n>1024&&i<u.length-1){n/=1024;i++;}return n.toFixed(1)+u[i]}
function ragClass(r){return r==='RED'?'rag-red':(r==='AMBER'?'rag-amber':'rag-green')}
function fmtNumber(n){return new Intl.NumberFormat('en-US').format(n||0)}

function appendVoiceLine(role,text){
  const box=document.getElementById('voiceTranscript');
  const who = role==='assistant' ? 'MINH AI (nữ)' : 'Anh Minh';
  box.innerHTML = `<div><b>${who}:</b> ${text}</div>` + box.innerHTML;
}

async function askMinh(message){
  const res = await fetch('/api/minh-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});
  const data = await res.json();
  if(!data.ok){ appendVoiceLine('assistant','Dạ em xin lỗi anh, em chưa xử lý được yêu cầu này ạ.'); return; }
  appendVoiceLine('assistant',data.reply);
  speakText(data.reply);
}

function speakText(text){
  const u = new SpeechSynthesisUtterance(text);
  u.lang='vi-VN';
  u.rate=1.0; u.pitch=1.15;
  const voices = speechSynthesis.getVoices();
  const v = voices.find(x=>x.lang && x.lang.toLowerCase().startsWith('vi') && /female|nữ/i.test(x.name)) || voices.find(x=>x.lang && x.lang.toLowerCase().startsWith('vi'));
  if(v) u.voice=v;
  speechSynthesis.speak(u);
}

function initRecognition(){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR) return null;
  const r = new SR();
  r.lang='vi-VN';
  r.continuous=false;
  r.interimResults=false;
  r.onresult = (e)=>{
    const txt=e.results?.[0]?.[0]?.transcript||'';
    if(txt){
      appendVoiceLine('user',txt);
      askMinh(txt);
    }
  };
  r.onerror = ()=>{document.getElementById('voiceState').textContent='Trạng thái: lỗi nhận giọng nói';};
  r.onend = ()=>{speaking=false; document.getElementById('voiceState').textContent= voiceEnabled ? 'Trạng thái: sẵn sàng nghe' : 'Trạng thái: chưa bật';};
  return r;
}

function toggleVoice(){
  voiceEnabled=!voiceEnabled;
  document.getElementById('voiceBtn').textContent = voiceEnabled ? 'Tắt hội thoại' : 'Bắt đầu hội thoại';
  document.getElementById('voiceState').textContent = voiceEnabled ? 'Trạng thái: sẵn sàng nghe' : 'Trạng thái: chưa bật';
  if(voiceEnabled && !recog){recog=initRecognition();}
}

function startTalk(){
  if(!voiceEnabled){toggleVoice();}
  if(!recog){appendVoiceLine('assistant','Dạ trình duyệt chưa hỗ trợ nhận giọng nói ạ. Anh dùng ô nhập chữ giúp em nhé.');return;}
  try{ speaking=true; document.getElementById('voiceState').textContent='Trạng thái: đang nghe...'; recog.start(); }catch(e){}
}

function sendTyped(){
  const el=document.getElementById('voiceText');
  const txt=(el.value||'').trim();
  if(!txt) return;
  appendVoiceLine('user',txt);
  el.value='';
  askMinh(txt);
}

