import subprocess
import time
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

CHAT_MEMORY = []

WORKSPACE = Path('/home/openclaw_user/.openclaw/workspace')
TEAM_LOGS = WORKSPACE / 'team_logs'
SESSIONS_META = Path('/home/openclaw_user/.openclaw/agents/main/sessions/sessions.json')
PUBLIC_DIR = Path(__file__).parent / 'public'

CPU_LAST = None
CPU_LAST_TS = None

AUTH_USER = os.environ.get('OPS_COCKPIT_USER', 'minh')
AUTH_PASS = os.environ.get('OPS_COCKPIT_PASS', '')

TOKEN_BUDGET_DAILY = int(os.environ.get('OPS_TOKEN_BUDGET_DAILY', '1000000'))
USD_TO_VND = float(os.environ.get('OPS_USD_TO_VND', '26000'))
IN_USD_PER_1M = float(os.environ.get('OPS_IN_USD_PER_1M', '5'))
OUT_USD_PER_1M = float(os.environ.get('OPS_OUT_USD_PER_1M', '15'))


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        return ''


def cpu_usage_percent():
    global CPU_LAST, CPU_LAST_TS
    try:
        with open('/proc/stat', 'r', encoding='utf-8') as f:
            line = f.readline()
        parts = [float(x) for x in line.strip().split()[1:]]
        idle = parts[3] + parts[4]
        total = sum(parts)
        now = time.time()
        if CPU_LAST is None:
            CPU_LAST = (idle, total)
            CPU_LAST_TS = now
            return 0.0
        prev_idle, prev_total = CPU_LAST
        delta_idle = idle - prev_idle
        delta_total = total - prev_total
        CPU_LAST = (idle, total)
        CPU_LAST_TS = now
        if delta_total <= 0:
            return 0.0
        return round(100.0 * (1.0 - delta_idle / delta_total), 1)
    except Exception:
        return 0.0


def mem_info():
    out = {}
    try:
        with open('/proc/meminfo', 'r', encoding='utf-8') as f:
            for line in f:
                k, v = line.split(':', 1)
                out[k.strip()] = int(v.strip().split()[0]) * 1024
    except Exception:
        pass
    return out


def get_session_file():
    try:
        data = json.loads(read_text(SESSIONS_META) or '{}')
        if not data:
            return None
        # ưu tiên session telegram direct của anh Minh
        key = None
        for k in data.keys():
            if 'telegram:direct:1079299777' in k:
                key = k
                break
        if key is None:
            key = next(iter(data.keys()))
        sf = data[key].get('sessionFile')
        return Path(sf) if sf else None
    except Exception:
        return None


