            'load': {'l1': round(load1, 2), 'l5': round(load5, 2), 'l15': round(load15, 2)},
            'memory': {'total': mem_total, 'used': mem_used, 'available': mem_avail, 'usedPct': mem_pct},
            'swap': {'total': swap_total, 'used': swap_used, 'free': swap_free, 'usedPct': swap_pct},
