def generate_minh_reply(user_text: str):
    q = (user_text or '').strip()
    q_low = q.lower()
    data = build_payload()

    token = data['projects']['tokenToday']['total']
    remain_pct = data['projects']['tokenBudget']['remainingPct']
    vnd = data['projects']['costEstimate']['vnd']
    cpu = data['system']['cpuPercent']
    ram = data['system']['memory']['usedPct']
    blockers = data['projects']['blockerCount']

    def fnum(n):
        return f"{int(n):,}"

    if any(k in q_low for k in ['chào', 'hello', 'hi']):
        return 'Dạ em chào anh Minh ạ. Em luôn sẵn sàng hỗ trợ anh.'
    if any(k in q_low for k in ['token', 'hạn mức', 'chi phí']):
        return f"Dạ anh Minh, hôm nay đã dùng {fnum(token)} token, còn {remain_pct}%, chi phí ước tính {fnum(vnd)} VND ạ."
    if any(k in q_low for k in ['blocker', 'vướng mắc', 'nghẽn']):
        return f"Dạ anh Minh, hiện có {blockers} vướng mắc ưu tiên. Anh có thể mở mục ‘Vướng mắc ưu tiên xử lý’ để xem từng điểm và bối cảnh chi tiết ạ."
    if any(k in q_low for k in ['hiệu suất', 'vps', 'cpu', 'ram', 'tải']):
        return f"Dạ anh Minh, hiện CPU khoảng {cpu}%, RAM dùng khoảng {ram}%. Hệ thống đang vận hành ổn định ạ."

    return 'Dạ anh Minh, em đã nhận yêu cầu. Anh nói rõ thêm mục tiêu hoặc quyết định cần em hỗ trợ để em xử lý ngay ạ.'


class Handler(BaseHTTPRequestHandler):
    def _is_authorized(self):
        # Nếu không set password thì tạm thời mở (phục vụ local dev)
        if not AUTH_PASS:
            return True
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Basic '):
            return False
        try:
            raw = base64.b64decode(auth.split(' ', 1)[1]).decode('utf-8', errors='ignore')
            user, pw = raw.split(':', 1)
            return user == AUTH_USER and pw == AUTH_PASS
        except Exception:
            return False

    def _deny(self):
        self.send_response(401)
        self.send_header('WWW-Authenticate', 'Basic realm="Ops Cockpit"')
        self.end_headers()

    def _json(self, data, code=200):
        b = json.dumps(data, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if not self._is_authorized():
            return self._deny()

        if path == '/api/minh-chat':
            try:
                length = int(self.headers.get('Content-Length', '0'))
                raw = self.rfile.read(length).decode('utf-8', errors='ignore') if length > 0 else '{}'
                body = json.loads(raw or '{}')
                msg = (body.get('message') or '').strip()
                reply = generate_minh_reply(msg)
                CHAT_MEMORY.append({'user': msg, 'assistant': reply, 'ts': datetime.now(timezone.utc).isoformat()})
                if len(CHAT_MEMORY) > 30:
                    del CHAT_MEMORY[:-30]
                return self._json({'ok': True, 'reply': reply, 'voice': {'lang': 'vi-VN', 'gender': 'female'}, 'memorySize': len(CHAT_MEMORY)})
            except Exception as e:
                return self._json({'ok': False, 'error': str(e)}, code=400)

        self.send_response(404)
        self.end_headers()

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if path == '/health':
            return self._json({'ok': True, 'time': datetime.now(timezone.utc).isoformat()})

        if not self._is_authorized():
            return self._deny()

        if path == '/api/metrics':
            return self._json(build_payload())

        # static files
        file_path = PUBLIC_DIR / ('index.html' if path == '/' else path.lstrip('/'))
        if file_path.exists() and file_path.is_file() and str(file_path.resolve()).startswith(str(PUBLIC_DIR.resolve())):
            ctype = 'text/html; charset=utf-8'
            if file_path.suffix == '.js':
                ctype = 'application/javascript; charset=utf-8'
            elif file_path.suffix == '.css':
                ctype = 'text/css; charset=utf-8'
            content = file_path.read_bytes()
            self.send_response(200)
            self.send_header('Content-Type', ctype)
            self.send_header('Content-Length', str(len(content)))
            self.end_headers()
            self.wfile.write(content)
            return

        self.send_response(404)
        self.end_headers()


if __name__ == '__main__':
    port = int(os.environ.get('OPS_COCKPIT_PORT', '18888'))
    use_tls = os.environ.get('OPS_COCKPIT_TLS', '0') == '1'
    cert_path = os.environ.get('OPS_COCKPIT_TLS_CERT', '/etc/ssl/ops-cockpit/cert.pem')
    key_path = os.environ.get('OPS_COCKPIT_TLS_KEY', '/etc/ssl/ops-cockpit/key.pem')

    server = ThreadingHTTPServer(('0.0.0.0', port), Handler)
    if use_tls:
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        ctx.load_cert_chain(certfile=cert_path, keyfile=key_path)
        server.socket = ctx.wrap_socket(server.socket, server_side=True)
        print(f'Ops Cockpit HTTPS running on :{port}')
    else:
        print(f'Ops Cockpit HTTP running on :{port}')

    server.serve_forever()

