async function askMinh(message){
  const res = await fetch('/api/minh-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message, attachments: chatAttachments})});
  const data = await res.json();
  if(!data.ok){ appendVoiceLine('assistant','Dạ em xin lỗi anh, em chưa xử lý được yêu cầu này ạ.'); return; }
  appendVoiceLine('assistant',data.reply);
  speakText(data.reply);
  chatAttachments=[];
}

async function uploadBase64Image(imageData, source='upload'){
  const res = await fetch('/api/upload-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({imageData, source})});
  const data = await res.json();
  if(!data.ok){ appendVoiceLine('assistant','Dạ em chưa nhận được ảnh hợp lệ ạ.'); return; }
  chatAttachments.push({type:'image', url:data.url});
  appendVoiceLine('user',`[Đã đính kèm ảnh] ${data.url}`);
}

function pickImage(){ document.getElementById('imgPicker').click(); }

function uploadPickedImage(ev){
  const f = ev.target.files && ev.target.files[0];
  if(!f) return;
  const rd = new FileReader();
  rd.onload = ()=> uploadBase64Image(rd.result, 'picker');
  rd.readAsDataURL(f);
  ev.target.value='';
}

async function captureImage(){
  const video=document.getElementById('camPreview');
  const canvas=document.getElementById('camCanvas');

  if(!camStream){
    try{
      camStream = await navigator.mediaDevices.getUserMedia({video:true});
      video.srcObject = camStream;
      video.style.display='block';
      appendVoiceLine('assistant','Dạ em đã bật camera. Anh bấm lại nút Chụp ảnh để chụp ạ.');
      return;
    }catch(e){
      appendVoiceLine('assistant','Dạ em không mở được camera, anh kiểm tra quyền truy cập giúp em ạ.');
      return;
    }
  }

  const w = video.videoWidth || 640;
  const h = video.videoHeight || 480;
  canvas.width=w; canvas.height=h;
  const ctx=canvas.getContext('2d');
  ctx.drawImage(video,0,0,w,h);
  const dataUrl = canvas.toDataURL('image/png');
  await uploadBase64Image(dataUrl, 'camera');
}

